script:
$w = New-Object -ComObject WScript.Shell
switch ("{{action}}") {
    "up"     { for($i=0; $i -lt 5; $i++) { $w.SendKeys([char]175) }; return "Volume increased" }
    "down"   { for($i=0; $i -lt 5; $i++) { $w.SendKeys([char]174) }; return "Volume decreased" }
    "mute"   { $w.SendKeys([char]173); return "Volume muted" }
    "unmute" { $w.SendKeys([char]173); return "Volume unmuted" }
    default  { return "Volume adjusted" }
}

$w = New-Object -ComObject WScript.Shell
switch ("{{operation}}") {
    "play_pause" { $w.SendKeys([char]179); return "Toggled play/pause" }
    "next"       { $w.SendKeys([char]176); return "Skipped to next track" }
    "prev"       { $w.SendKeys([char]177); return "Returned to previous track" }
    default      { return "Media key sent" }
}

$target = "{{app_name}}".Trim()
$proc = Get-Process | Where-Object { $_.ProcessName -like "*$target*" -or $_.MainWindowTitle -like "*$target*" } | Select-Object -First 1
if ($proc -and $proc.MainWindowHandle -ne 0) {
    $ws = New-Object -ComObject WScript.Shell
    $ws.AppActivate($proc.Id) | Out-Null
    return "Brought $($proc.ProcessName) to focus"
} else {
    Start-Process $target -ErrorAction SilentlyContinue
    return "Launched $target"
}

$w = New-Object -ComObject WScript.Shell
switch ("{{action}}") {
    "minimize"   { $w.SendKeys("% n"); return "Minimized window" }
    "maximize"   { $w.SendKeys("% x"); return "Maximized window" }
    "desktop"    { (New-Object -ComObject Shell.Application).ToggleDesktop(); return "Toggled desktop" }
    "close"      { $w.SendKeys("%{F4}"); return "Closed window" }
    default      { return "Window action completed" }
}

$q = "{{query}}".Trim()
if ($q -match "^https?://") {
    Start-Process $q
    return "Opened $q"
} else {
    $enc = [Uri]::EscapeDataString($q)
    Start-Process "https://www.google.com/search?q=$enc"
    return "Searched web for '$q'"
}

if ("{{action}}" -eq "clear") {
    Set-Clipboard -Value ""
    return "Clipboard cleared"
} else {
    $c = Get-Clipboard
    if ($c) { return "Clipboard: $c" } else { return "Clipboard is empty" }
}

$target = "{{profile}}".Trim()
if (-not $target) {
    $cur = (netsh wlan show interfaces) | Select-String "SSID\s*:\s*(.+)" | ForEach-Object { $_.Matches[0].Groups[1].Value.Trim() } | Select-Object -First 1
    if ($cur) { $target = $cur }
}
if ($target) {
    $xml = netsh wlan show profile name="$target" key=clear 2>$null
    $pass = $xml | Select-String "Key Content\s*:\s*(.+)" | ForEach-Object { $_.Matches[0].Groups[1].Value.Trim() } | Select-Object -First 1
    if ($pass) { return "Wi-Fi '$target' Password: $pass" }
    else { return "No password required or not found for '$target'" }
} else {
    $profiles = (netsh wlan show profiles) | Select-String "All User Profile\s*:\s*(.+)" | ForEach-Object { $_.Matches[0].Groups[1].Value.Trim() }
    return "Known Wi-Fi networks: " + ($profiles -join ", ")
}

if ("{{action}}" -eq "report") {
    $reportPath = "$env:TEMP\battery-report.html"
    powercfg /batteryreport /output "$reportPath" | Out-Null
    if (Test-Path $reportPath) {
        Start-Process "$reportPath"
        return "Generated and opened full battery diagnostic report"
    }
}
$b = Get-CimInstance -ClassName Win32_Battery -ErrorAction SilentlyContinue
if ($b) {
    $status = switch ($b.BatteryStatus) { 1 {"Discharging"} 2 {"On AC Power"} 3 {"Fully Charged"} 4 {"Low"} 5 {"Critical"} 6 {"Charging"} default {"Unknown"} }
    return "Battery: $($b.EstimatedChargeRemaining)% ($status), Est. Runtime: $($b.EstimatedRunTime) mins"
} else {
    return "No physical battery detected (Desktop PC or virtualized system)"
}

$tempPaths = @($env:TEMP, "$env:SystemRoot\Temp")
$freedCount = 0
foreach ($p in $tempPaths) {
    if (Test-Path $p) {
        Get-ChildItem -Path $p -Recurse -Force -ErrorAction SilentlyContinue |
            Where-Object { -not $_.PSIsContainer } |
            ForEach-Object {
                try { Remove-Item $_.FullName -Force -ErrorAction Stop; $freedCount++ } catch {}
            }
    }
}
return "Cleaned up $freedCount temporary files from cache"

$t = "{{target}}".Trim()
if ($t -eq "hung" -or $t -eq "unresponsive") {
    $hung = Get-Process | Where-Object { $_.Responding -eq $false }
    if ($hung) {
        $hung | Stop-Process -Force
        return "Killed unresponsive processes: " + ($hung.ProcessName -join ", ")
    } else {
        return "No unresponsive processes detected"
    }
} else {
    $procs = Get-Process | Where-Object { $_.ProcessName -like "*$t*" }
    if ($procs) {
        $procs | Stop-Process -Force
        return "Terminated $($procs.Count) instance(s) of $t"
    } else {
        return "No running process matched '$t'"
    }
}

$term = "{{search_term}}".Trim()
$folders = @(
    [Environment]::GetFolderPath('Desktop'),
    [Environment]::GetFolderPath('MyDocuments'),
    (Join-Path $env:USERPROFILE 'Downloads'),
    (Join-Path $env:USERPROFILE 'Pictures')
)
$results = @()
foreach ($dir in $folders) {
    if (Test-Path $dir) {
        $results += Get-ChildItem -Path $dir -Recurse -Force -ErrorAction SilentlyContinue -Filter "*$term*" |
            Select-Object -First 15 | ForEach-Object {
                "$($_.FullName)  ($([math]::Round($_.Length / 1KB, 1)) KB)"
            }
    }
}
if ($results.Count -gt 0) {
    return "Found $($results.Count) file(s) matching '$term':`n" + ($results | Select-Object -First 20 | Out-String)
} else {
    return "No files found matching '$term' in Desktop, Documents, Downloads, or Pictures"
}

$requested = "{{folder}}".Trim().Trim('"').Trim("'")
$folderMap = @{
    "downloads"  = Join-Path $env:USERPROFILE "Downloads"
    "documents"  = [Environment]::GetFolderPath('MyDocuments')
    "desktop"    = [Environment]::GetFolderPath('Desktop')
    "pictures"   = [Environment]::GetFolderPath('MyPictures')
    "music"      = [Environment]::GetFolderPath('MyMusic')
    "videos"     = [Environment]::GetFolderPath('MyVideos')
    "home"       = $env:USERPROFILE
    "appdata"    = $env:APPDATA
    "temp"       = $env:TEMP
    "startup"    = Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs\Startup"
    "recycle"    = "shell:RecycleBinFolder"
}
$key = $requested.ToLower()
if ($folderMap.ContainsKey($key)) {
    $target = $folderMap[$key]
    if ($key -eq "recycle") { Start-Process explorer.exe -ArgumentList "shell:RecycleBinFolder"; return "Opened recycle bin" }
    Start-Process explorer.exe -ArgumentList "$target"
    return "Opened $key folder"
}
# Literal path (absolute, relative, or ~/user paths)
$candidate = $requested
if ($candidate.StartsWith("~")) { $candidate = Join-Path $env:USERPROFILE $candidate.Substring(1).TrimStart('\','/') }
if ((Test-Path $candidate -PathType Container)) {
    $full = (Resolve-Path $candidate).Path
    Start-Process explorer.exe -ArgumentList "$full"
    return "Opened folder $full"
}
# Search common locations for a directory with this name:
# fixed local drive roots (two levels, e.g. D:\Codee\desktop_agent)
# + user folders (top level). Only Fixed drives are scanned:
# network/disconnected drives can stall enumeration for seconds.
$searchRoots = @()
foreach ($d in ([IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady })) {
    $searchRoots += $d.RootDirectory.FullName
}
$secondLevelRoots = @()
foreach ($root in $searchRoots) {
    try {
        $secondLevelRoots += Get-ChildItem -Path $root -Directory -Force -ErrorAction SilentlyContinue |
            Select-Object -ExpandProperty FullName
    } catch {}
}
$searchRoots += @(
    [Environment]::GetFolderPath('Desktop'),
    [Environment]::GetFolderPath('MyDocuments'),
    (Join-Path $env:USERPROFILE 'Downloads'),
    $env:USERPROFILE
)
$searchRoots += $secondLevelRoots
foreach ($root in ($searchRoots | Select-Object -Unique)) {
    if (-not (Test-Path $root)) { continue }
    try {
        $hit = Get-ChildItem -Path $root -Directory -Force -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -ieq $requested } | Select-Object -First 1
        if ($hit) {
            Start-Process explorer.exe -ArgumentList $hit.FullName
            return "Opened folder $($hit.FullName)"
        }
    } catch {}
}
return "ERROR: Could not find a folder named '$requested'. Checked system folders, '$candidate', drive roots, Desktop, Documents, and Downloads."

$actionMap = @{ "up" = 20; "down" = -20; "max" = 100; "min" = 10; "half" = 50 }
$action = "{{action}}"
try {
    $current = (Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightness -ErrorAction Stop).CurrentBrightness
    if ($action -eq "max") { $new = 100 }
    elseif ($action -eq "min") { $new = 10 }
    elseif ($action -eq "half") { $new = 50 }
    elseif ($action -eq "down") { $new = [Math]::Max(5, $current - 20) }
    else { $new = [Math]::Min(100, $current + 20) }
    (Get-CimInstance -Namespace root/WMI -ClassName WmiMonitorBrightnessMethods).WmiSetBrightness(1, $new)
    return "Brightness changed: $current% -> $new%"
} catch {
    return "Brightness control not available on this display (external monitors may not support WMI brightness)"
}

$folders = @(
    [Environment]::GetFolderPath('Desktop'),
    [Environment]::GetFolderPath('MyDocuments'),
    (Join-Path $env:USERPROFILE 'Downloads'),
    (Join-Path $env:USERPROFILE 'Videos'),
    $env:TEMP
)
$allFiles = @()
foreach ($dir in $folders) {
    if (Test-Path $dir) {
        $allFiles += Get-ChildItem -Path $dir -Recurse -File -ErrorAction SilentlyContinue | Select-Object FullName, Length
    }
}
$top = $allFiles | Sort-Object Length -Descending | Select-Object -First 15 |
    ForEach-Object { "$([math]::Round($_.Length / 1MB, 1)) MB  -  $($_.FullName)" }
if ($top) { return "Largest files found:`n" + ($top -join "`n") }
else { return "No large files found" }

$procs = Get-Process | Where-Object { $_.MainWindowTitle -ne '' -and $_.ProcessName -notmatch '^(svchost|system|csrss|smss|lsass|dwm|conhost)$' } |
    Sort-Object WorkingSet64 -Descending |
    Select-Object -First 20 |
    ForEach-Object { "$($_.ProcessName) — $($_.MainWindowTitle.Substring(0, [Math]::Min(50, $_.MainWindowTitle.Length)))  [$([math]::Round($_.WorkingSet64/1MB,0)) MB]" }
if ($procs) { return "Running Applications:`n" + ($procs -join "`n") }
else { return "No visible applications running" }

switch ("{{action}}") {
    "shutdown_30"  { shutdown /s /t 1800 /c "WinBrow: Shutting down in 30 minutes"; return "Shutdown scheduled in 30 minutes. Cancel with: shutdown /a" }
    "shutdown_60"  { shutdown /s /t 3600 /c "WinBrow: Shutting down in 1 hour"; return "Shutdown scheduled in 1 hour. Cancel with: shutdown /a" }
    "shutdown_120" { shutdown /s /t 7200 /c "WinBrow: Shutting down in 2 hours"; return "Shutdown scheduled in 2 hours. Cancel with: shutdown /a" }
    "restart_30"   { shutdown /r /t 1800 /c "WinBrow: Restarting in 30 minutes"; return "Restart scheduled in 30 minutes. Cancel with: shutdown /a" }
    "cancel"       { shutdown /a 2>$null; return "Cancelled any pending shutdown or restart" }
}

try {
    $ip = (Invoke-WebRequest -Uri "https://api.ipify.org" -UseBasicParsing -TimeoutSec 5).Content
    Add-Type -AssemblyName System.Windows.Forms
    [System.Windows.Forms.Clipboard]::SetText($ip)
    return "Public IP: $ip (copied to clipboard)"
} catch {
    return "Could not fetch public IP — check internet connection"
}

$downloads = Join-Path $env:USERPROFILE 'Downloads'
$archive = Join-Path $downloads "Old_Downloads_$(Get-Date -Format 'yyyy-MM-dd')"
$cutoff = (Get-Date).AddDays(-30)
$old = Get-ChildItem -Path $downloads -File -ErrorAction SilentlyContinue |
    Where-Object { $_.LastWriteTime -lt $cutoff -and $_.Name -notlike "Old_Downloads*" }
if ($old.Count -gt 0) {
    New-Item -ItemType Directory -Path $archive -Force | Out-Null
    $old | Move-Item -Destination $archive
    return "Moved $($old.Count) file(s) older than 30 days to $archive"
} else {
    return "No old files found in Downloads (everything is less than 30 days old)"
}

$ref = "{{image}}".Trim()
if (-not $ref) {
    return "Tell me which image to use, e.g. 'set wallpaper to C:\Pictures\sunset.jpg' or 'set wallpaper to sunset'."
}
$candidate = $ref
if ($ref.StartsWith("~")) { $candidate = Join-Path $env:USERPROFILE $ref.Substring(1).TrimStart('\','/') }
if (-not (Test-Path $candidate -PathType Leaf)) {
    $roots = @(
        [Environment]::GetFolderPath('MyPictures'),
        [Environment]::GetFolderPath('Desktop'),
        (Join-Path $env:USERPROFILE 'Downloads')
    )
    $found = $null
    foreach ($root in $roots) {
        if (-not (Test-Path $root)) { continue }
        $found = Get-ChildItem -Path $root -File -Include *.jpg,*.jpeg,*.png,*.bmp -ErrorAction SilentlyContinue |
            Where-Object { $_.BaseName -like "*$ref*" } | Select-Object -First 1
        if ($found) { break }
    }
    if ($found) { $candidate = $found.FullName }
    else { return "ERROR: Could not find an image matching '$ref' in Pictures, Desktop, or Downloads. Provide a full image path." }
}
Add-Type -TypeDefinition 'using System;using System.Runtime.InteropServices;public class WPP{[DllImport("user32.dll",CharSet=CharSet.Auto)]public static extern int SystemParametersInfo(int a,int b,string c,int d);}'
[WPP]::SystemParametersInfo(20, 0, $candidate, 3) | Out-Null
return "Desktop wallpaper set to $candidate"

$ref = "{{folder}}".Trim().Trim('"').Trim("'")
$folderMap = @{
    "downloads" = Join-Path $env:USERPROFILE "Downloads"
    "documents" = [Environment]::GetFolderPath('MyDocuments')
    "desktop"   = [Environment]::GetFolderPath('Desktop')
    "pictures"  = [Environment]::GetFolderPath('MyPictures')
    "music"     = [Environment]::GetFolderPath('MyMusic')
    "videos"    = [Environment]::GetFolderPath('MyVideos')
    "home"      = $env:USERPROFILE
}
$target = $folderMap[$ref.ToLower()]
if (-not $target) {
    if ($ref.StartsWith("~")) { $target = Join-Path $env:USERPROFILE $ref.Substring(1).TrimStart('\','/') }
    else { $target = $ref }
}
try { $target = (Resolve-Path $target -ErrorAction Stop).Path } catch {}
$target = $target.TrimEnd('\')
$shell = New-Object -ComObject Shell.Application
$closed = 0
foreach ($w in $shell.Windows()) {
    try {
        $loc = $w.LocationURL
        if (-not $loc) { continue }
        $path = ([Uri]::UnescapeDataString(($loc -replace '^file:///','') -replace '/','\')).TrimEnd('\')
        if ($path -ieq $target) { $w.Quit(); $closed++ }
    } catch {}
}
if ($closed -gt 0) { return "Closed $closed Explorer window(s) showing $target" }
else { return "No open Explorer window found showing '$ref'." }

$ref = "{{target}}".Trim().Trim('"').Trim("'")
$app = "{{app}}".Trim().ToLower()
if (-not $ref) {
    return "Tell me which file to open, e.g. 'open the file report.pdf'."
}
$path = $null
$candidate = $ref
if ($ref.StartsWith("~")) { $candidate = Join-Path $env:USERPROFILE $ref.Substring(1).TrimStart('\','/') }
if (Test-Path $candidate -PathType Leaf) { $path = (Resolve-Path $candidate).Path }
if (-not $path) {
    $roots = @(
        [Environment]::GetFolderPath('Desktop'),
        [Environment]::GetFolderPath('MyDocuments'),
        (Join-Path $env:USERPROFILE 'Downloads'),
        [Environment]::GetFolderPath('MyPictures'),
        [Environment]::GetFolderPath('MyVideos'),
        [Environment]::GetFolderPath('MyMusic'),
        $env:USERPROFILE
    )
    $hits = @()
    foreach ($root in ($roots | Select-Object -Unique)) {
        if (-not (Test-Path $root)) { continue }
        try {
            $hits += Get-ChildItem -Path $root -Recurse -File -ErrorAction SilentlyContinue -Depth 3 |
                Where-Object { $_.Name -ieq $ref -or $_.BaseName -ieq $ref }
        } catch {}
    }
    if ($hits.Count -eq 0) {
        return "ERROR: Could not find a file named '$ref' in Desktop, Documents, Downloads, Pictures, Videos, or Music."
    }
    $best = $hits | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    $path = $best.FullName
}
if ($app -match "chrome|edge|browser") {
    $exe = $null
    foreach ($p in @(
        "$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
        "$env:ProgramFiles(x86)\Google\Chrome\Application\chrome.exe",
        "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe",
        "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe",
        "$env:ProgramFiles(x86)\Microsoft\Edge\Application\msedge.exe"
    )) { if (Test-Path $p) { $exe = $p; break } }
    if ($exe) {
        Start-Process $exe -ArgumentList "$path"
        return "Opened $path in $([IO.Path]::GetFileNameWithoutExtension($exe))"
    }
}
Start-Process "$path"
$extra = ""
return "Opened $path$extra"
